6	describe("skill catalog", () => {
7	  test("has valid, unique metadata and non-empty instructions", () => {
8	    const files: string[] = [];
9	    const collect = (directory: string): void => {
10	      for (const entry of readdirSync(directory, { withFileTypes: true })) {
11	        const path = join(directory, entry.name);
12	        if (entry.isDirectory()) collect(path);
13	        else if (entry.isFile() && entry.name.endsWith(".md")) files.push(path);
14	      }
15	    };
16	    collect("src/content/skills");
17	
18	    const names = new Set<string>();
19	    for (const file of files) {
20	      const document = readFileSync(file, "utf8");
21	      // `\r?` on every newline: a Windows checkout has CRLF line endings, and without
22	      // it this matched nothing at all -- so the test failed for anyone working on
23	      // Windows and passed in CI, which is the least useful place for a check to
24	      // disagree with the person it is checking.
25	      const match = document.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]+)$/);
26	      expect(match, `${file} must have YAML frontmatter and a body`).not.toBeNull();
27	      const metadata = Bun.YAML.parse(match![1]!) as { name?: string; description?: string };
28	      expect(metadata.name?.trim(), `${file} name`).toBeTruthy();
29	      expect(metadata.description?.trim(), `${file} description`).toBeTruthy();
30	      expect(match![2]!.trim(), `${file} instructions`).toBeTruthy();
31	      expect(names.has(metadata.name!), `duplicate skill name: ${metadata.name}`).toBe(false);
32	      names.add(metadata.name!);
33	    }
34	
35	    // Not an exact count. What this guards is that the walk found anything at
36	    // all — a mistyped directory would make every check above vacuous and the
37	    // test would pass on zero files. Pinning the number instead made adding a
38	    // skill a test edit, which taught nothing and caught nothing.
39	    expect(files.length, "no skills found; check the walk's starting directory").toBeGreaterThan(0);
40	  });
41	
42	  /**
43	   * A skill names its tools the way a run reaches them, and that means bare.
44	   *
45	   * Every server in `tools/defaults.yaml` sets `unprefixed: true`, so a tool is
46	   * registered under its own name — `probe`, `create_pr`, `bash` — and
47	   * `server__tool` names nothing. This is not a style rule: a skill that says
48	   * `attachments__publish_draft` tells an agent to call a tool that does not
49	   * exist, the call comes back unknown, and the skill's own "if this tool is not
50	   * among yours, the layer is not deployed" branch then reports a deployment gap
51	   * about a tool that is right there. Measured on `docs/design-doc`'s first
52	   * draft, which spelled all six of its tool references that way.
53	   *
54	   * The `atoma_builtin__` prefix is the core's own and is not covered: it names
55	   * the tools atoma adds itself, whose spelling no skill here decides.
56	   */
57	  test("a skill does not write a shipped server's tool as `server__tool`", () => {
58	    const servers = Object.keys(toolDefaults().servers);
59	    const files: string[] = [];
60	    const collect = (directory: string): void => {
61	      for (const entry of readdirSync(directory, { withFileTypes: true })) {
62	        const path = join(directory, entry.name);
63	        if (entry.isDirectory()) collect(path);
64	        else if (entry.isFile() && entry.name.endsWith(".md")) files.push(path);
65	      }
66	    };
67	    collect("src/content/skills");
68	
69	    const wrong: string[] = [];
70	    for (const file of files) {
71	      const document = readFileSync(file, "utf8");
72	      for (const server of servers) {
73	        for (const match of document.matchAll(new RegExp(`\`${server}__([a-z_]+)\``, "g"))) {
74	          wrong.push(`${file}: \`${server}__${match[1]}\` — call it \`${match[1]}\``);
75	        }
76	      }
77	    }
78	    expect(
79	      wrong,
80	      "a shipped server is `unprefixed`, so its tools are called by their own names; a name " +
81	        "carrying the server prefix is one no run has",
82	    ).toEqual([]);
83	  });
84	});

