129	function copyStaticAtomatonContent(): void {
130	  const srcAtomatonDir = from(USER_ROOT);
131	  const distAtomatonDir = into(USER_ROOT);
132	
133	  // Every static file the generated workflows read at runtime must be listed
134	  // here, or it never reaches `dist/` and so never reaches an adopter. A file
135	  // missing from this list is invisible in review: it keeps working in whatever
136	  // `.github/` already has it and is simply absent from everyone else's.
137	  // `deployment-contract.test.ts` keeps this list in step with `src/content/`.
138	  // README.md is here for the same reason the rest is: an adopter who opens this
139	  // directory should find out what each path means without leaving it.
140	  const filesCopiedVerbatim = ["README.md", "config.yaml", "prompt-template.md"];
141	
142	  // A file dropped from that list, or renamed, is still sitting in `dist/` from
143	  // the last build -- `cpSync` adds and never removes. It then ships: the release
144	  // manifest is built by walking `dist/`, so the orphan is listed as part of the
145	  // release and unzipped into an adopter's repository. `config.json` became
146	  // `config.yaml` and both were in the archive until this ran.
147	  //
148	  // `tools/` is swept too, and for a sharper reason: `tools.yaml` used to be written
149	  // there and is not any more. A stale one would keep shipping, and an adopter with a
150	  // tools file in their tree is an adopter whose runs read it -- the whole defect this
151	  // change removes, preserved by a build artifact nobody deleted. Only `scripts/`
152	  // belongs under it now, and `bundleTree` replaced that before this runs.
153	  //
154	  // The subdirectories of `atoma/` itself are replaced wholesale below, so files at
155	  // these two levels are all that can be orphaned.
156	  const sweep: Array<[string, readonly string[]]> = [[distAtomatonDir, filesCopiedVerbatim]];
157	  for (const [dir, keep] of sweep) {
158	    if (!existsSync(dir)) continue;
159	    for (const entry of readdirSync(dir, { withFileTypes: true })) {
160	      if (entry.isFile() && !keep.includes(entry.name)) {
161	        rmSync(join(dir, entry.name));
162	        console.log(`build-dist: removed ${join(dir, entry.name)}, left over from an earlier build`);
163	      }
164	    }
165	  }
166	
167	  for (const file of filesCopiedVerbatim) {
168	    cpSync(join(srcAtomatonDir, file), join(distAtomatonDir, file));
169	  }
170	  copyDirectoryFresh(join(srcAtomatonDir, "agent-definitions"), join(distAtomatonDir, "agent-definitions"));
171	  copyDirectoryFresh(join(srcAtomatonDir, "skills"), join(distAtomatonDir, "skills"));
172	  // Not read by anything at runtime -- an adopter applies it once with `gh api`.
173	  // It ships because the required check it names is produced by a workflow that
174	  // also ships, and a ruleset written by hand against a remembered job name is
175	  // the failure `generated-workflows.test.ts` exists to prevent.
176	  copyDirectoryFresh(join(srcAtomatonDir, "rulesets"), join(distAtomatonDir, "rulesets"));
177	
178	  // The runtime's own data, beside the scripts that read it and outside the directory
179	  // an adopter edits. `defaults.yaml` is read by `write_tools_file.ts` at the start of
180	  // every run and by `validate_deliverable.ts` on every pull request; `packages.json`
181	  // is what the install step reads. Neither is a copy of anything in `.github/atomaton/`.
182	  const srcRuntimeTools = from(TOOLS_DIR);
183	  const distRuntimeTools = into(TOOLS_DIR);
184	  mkdirSync(distRuntimeTools, { recursive: true });
185	  for (const file of ["defaults.yaml", "packages.json"]) {
186	    cpSync(join(srcRuntimeTools, file), join(distRuntimeTools, file));
187	  }
188	  // The delegate's own files: the roster, and each definition's `agent.md` and
189	  // `tools.yaml`. Copied rather than bundled, because they are data the server reads
190	  // at run time.
191	  //
192	  // They come from `content/` and land under `.github/atomaton/`, which is the
193	  // directory an upgrade does not overwrite without a person deciding: a `model:`
194	  // line is the thing a project most wants to change about a delegate, and it used to
195	  // be in a file the next release replaced. See `DELEGATES_DIR` in
196	  // `domain/machinery/machinery-layout.ts`.
197	  copyDirectoryFresh(join(srcAtomatonDir, "delegates"), join(distAtomatonDir, "delegates"));
198	  // And NOT under `.github/atomaton/agent-definitions/`, which is the namespace a
199	  // person dispatches from. A definition there is a `/<name>` a person can type, an
200	  // entry in every agent's colleague list, and a valid value for
201	  // `agents.on_config_finding` — none of which a delegate is. See `mcp/delegate.ts`.
202	  // The tools file is NOT built here and does NOT ship. `write_tools_file.ts` writes
203	  // it per run, from the config, into the runner's temp directory.
204	  //
205	  // It used to be generated here and put in the release, which meant an adopter
206	  // received a config and a file generated from it, with nothing on their side able
207	  // to regenerate one from the other -- so editing `tools.servers` did nothing, or,
208	  // if they added a server, blocked every run. A generated file that is distributed
209	  // is a second source of truth wearing the clothes of a first.
210	  //
211	  // The collision check that lived here went with it: a name is only reserved at the
212	  // moment the file is written, and that moment is now in the adopter's run, where
213	  // this build cannot see it.
214	
215	  console.log(`build-dist: copied static content: ${srcAtomatonDir} -> ${distAtomatonDir}`);
216	}
