218	/**
219	 * Write what this release is and what it contains.
220	 *
221	 * Last, because it lists what the steps above produced -- including the generated
222	 * workflows, which `synth-workflows.ts` wrote before any of this ran. Walking `dist/` rather
223	 * than assembling a list by hand is the point: a list written by hand is a list that
224	 * disagrees with the zip the first time somebody adds a file.
225	 *
226	 * See `domain/machinery/release-manifest.ts` for the two questions this answers.
227	 */
228	function writeManifest(): void {
229	  const version = `v${(JSON.parse(readFileSync(join(REPO_ROOT, "package.json"), "utf8")) as { version: string }).version}`;
230	  const files: string[] = [];
231	  const walk = (dir: string, prefix: string) => {
232	    for (const entry of readdirSync(dir, { withFileTypes: true })) {
233	      const here = `${prefix}/${entry.name}`;
234	      if (entry.isDirectory()) walk(join(dir, entry.name), here);
235	      else files.push(here);
236	    }
237	  };
238	  walk(DIST_GITHUB_DIR, ".github");
239	
240	  const manifest = buildManifest(version, files);
241	  writeFileSync(join(REPO_ROOT, "dist", RELEASE_MANIFEST), `${JSON.stringify(manifest, null, 2)}\n`);
242	  console.log(`build-dist: wrote ${RELEASE_MANIFEST} for ${version} (${manifest.files.length} files)`);
243	}
244	
245	async function main(): Promise<void> {
246	  await bundleTree(from(SCRIPTS_DIR), into(SCRIPTS_DIR), new Set(["lib", "testing"]));
247	  await bundleTree(from(TOOLS_DIR), into(TOOLS_DIR), new Set(["lib"]));
248	  copyStaticAtomatonContent();
249	  writeManifest();
250	}
251	
252	void main();
