1	/**
2	 * deployment-contract.test.ts — every static Atomaton file reaches the deployed
3	 * `.github/`.
4	 *
5	 * A repository adopts the deliverable by copying it over its own `.github/`:
6	 *
7	 *     cp -r dist/.github/. .github/
8	 *
9	 * So a file that exists only under `.github/` is not part of the deliverable at
10	 * all. It keeps working wherever it already sits and is simply missing
11	 * everywhere else, which leaves no diff and so cannot be caught in review. That
12	 * is the failure this file exists to make loud, and it is why the check is
13	 * against `src/content/` and `build-dist.ts` rather than against any deployed
14	 * tree.
15	 *
16	 * This already happened: a PR added a package list under `.github/atomaton/` by hand
17	 * without adding it to `src/content/` or to build-dist.ts's copy list, while
18	 * switching tools.yaml to a binary that only that file installs.
19	 */
20	import { describe, expect, test } from "bun:test";
21	import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
22	import { join, relative } from "node:path";
23	import { sourceOf, TOOLS_DIR, USER_ROOT } from "../../src/domain/machinery/machinery-layout.ts";
24	
25	// Both from the one table, so a source tree that moves again cannot leave this
26	// checking a directory that is not there. `BUILT_FROM` is what `build-dist.ts`
27	// itself reads, and this file is about the two of them agreeing.
28	const ATOMA_SRC = join(process.cwd(), "src", sourceOf(USER_ROOT));
29	const RUNTIME_TOOLS = join(process.cwd(), "src", sourceOf(TOOLS_DIR));
30	const BUILD_DIST = join(process.cwd(), "src/build-dist.ts");
31	
32	/** Filenames in build-dist.ts's verbatim-copy list. */
33	function copiedFiles(): string[] {
34	  const source = readFileSync(BUILD_DIST, "utf8");
35	  // The declaration, not the loop that consumes it. Matching the loop broke the
36	  // moment the list was given a name so that the same array could also decide
37	  // which leftovers to sweep out of `dist/`.
38	  const list = /const filesCopiedVerbatim = \[([^\]]*)\]/.exec(source)?.[1];
39	  if (!list) throw new Error("could not locate build-dist.ts's static copy list (`filesCopiedVerbatim`)");
40	  return [...list.matchAll(/"([^"]+)"/g)].map((m) => m[1] as string);
41	}
42	
43	/**
44	 * Loose static files sitting directly in src/content/, i.e. the ones that have to
45	 * be named in build-dist.ts's copy list. Restricted to shippable data
46	 * extensions: anything else in there is a stray, which the first test below
47	 * reports on its own terms rather than as a missing copy-list entry.
48	 */
49	function staticFiles(): string[] {
50	  return readdirSync(ATOMA_SRC, { withFileTypes: true })
51	    .filter((e) => e.isFile() && /\.(json|md|ya?ml)$/.test(e.name))
52	    .map((e) => e.name);
53	}
54	
55	/** Every file under a directory, recursively, repo-relative. */
56	function walk(dir: string): string[] {
57	  const out: string[] = [];
58	  for (const entry of readdirSync(dir, { withFileTypes: true })) {
59	    const path = join(dir, entry.name);
60	    if (entry.isDirectory()) out.push(...walk(path));
61	    else out.push(relative(process.cwd(), path).replaceAll("\\", "/"));
62	  }
63	  return out;
64	}
65	
66	describe("deployment contract", () => {
67	  // `src/content/` is the deliverable, mirrored 1:1 into `dist/.github/atomaton/`
68	  // and from there into an adopter's own `.github/`. Anything that exists to
69	  // develop THIS repository belongs outside it, which is why these contract
70	  // tests live under `tests/`.
71	  //
72	  // The line, decided deliberately: a test of SHIPPED BEHAVIOUR lives beside the
73	  // shipped code, because it describes the product. A test of THIS REPO'S
74	  // build-and-deploy machinery lives here under `tests/`, because it describes
75	  // the factory. Neither ever ships — build-dist.ts excludes `*.test.ts`.
76	  //
77	  // So `src/entrypoints/tools/**` is exempt: `mcp.test.ts` and `shell_guard.test.ts`
78	  // exercise MCP servers that adopters receive and run, and a template repo that
79	  // shipped an untested MCP server would be handing adopters untested code.
80	  test("the deliverable's content directories hold no test files", () => {
81	    const strays = walk(ATOMA_SRC)
82	      .filter((f) => /\.test\.ts$|\.spec\.ts$/.test(f))
83	      .filter((f) => !f.startsWith("src/entrypoints/tools/"));
84	    expect(strays, `move these out of src/content/: ${strays.join(", ")}`).toEqual([]);
85	  });
